PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, google_sub TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin','provider')), profile TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invitations (email TEXT PRIMARY KEY, expires_at TEXT NOT NULL, invited_by TEXT, used_at TEXT);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE talks (id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, starts_at TEXT NOT NULL, duration INTEGER NOT NULL DEFAULT 45, capacity INTEGER NOT NULL DEFAULT 6 CHECK(capacity BETWEEN 4 AND 6), price INTEGER NOT NULL DEFAULT 1000 CHECK(price>=0), image TEXT NOT NULL, host TEXT NOT NULL, description TEXT NOT NULL, participants TEXT NOT NULL DEFAULT '[]', published INTEGER NOT NULL DEFAULT 0, meeting_url TEXT);
CREATE TABLE bookings (id TEXT PRIMARY KEY, talk_id TEXT NOT NULL REFERENCES talks(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('pending','confirmed','attended','cancelled','refund_pending','refunded')), amount INTEGER NOT NULL CHECK(amount>=0), stripe_session_id TEXT UNIQUE, payment_intent TEXT, expires_at INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX one_active_booking ON bookings(user_id,talk_id) WHERE status IN ('pending','confirmed','attended');
CREATE UNIQUE INDEX one_free_trial ON bookings(user_id) WHERE amount=0 AND status IN ('pending','confirmed','attended');
CREATE INDEX bookings_talk ON bookings(talk_id,status);
CREATE TABLE rooms (id TEXT PRIMARY KEY, title TEXT NOT NULL, subtitle TEXT NOT NULL, image TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE room_members (room_id TEXT NOT NULL REFERENCES rooms(id), user_id TEXT NOT NULL REFERENCES users(id), last_read_at TEXT NOT NULL DEFAULT '1970-01-01 00:00:00', PRIMARY KEY(room_id,user_id));
CREATE TABLE messages (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), user_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000), reply_to TEXT REFERENCES messages(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f','now')));
CREATE INDEX messages_room ON messages(room_id,created_at);
CREATE TABLE notes (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, image TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), verified_at TEXT NOT NULL, category TEXT NOT NULL, relation TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0);
CREATE TABLE providers (id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id), name TEXT NOT NULL, theme TEXT NOT NULL, bio TEXT NOT NULL, price TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, verified_by TEXT REFERENCES users(id), verified_at TEXT);
CREATE TABLE consultations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), provider_id TEXT NOT NULL REFERENCES providers(id), title TEXT NOT NULL, body TEXT NOT NULL, budget TEXT NOT NULL, desired_date TEXT NOT NULL, shared_messages TEXT NOT NULL DEFAULT '[]', consent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','accepted','completed','cancelled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX consultation_owner ON consultations(user_id,provider_id);
CREATE TABLE reports (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), reporter_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), ai_suggestion TEXT, reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE blocks (user_id TEXT NOT NULL REFERENCES users(id), blocked_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(user_id,blocked_id));
CREATE TABLE stripe_events (id TEXT PRIMARY KEY, type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE email_outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at TEXT);
CREATE TABLE activity (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), kind TEXT NOT NULL, target_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX activity_kind ON activity(kind,created_at);
CREATE TABLE costs (id TEXT PRIMARY KEY, fees INTEGER NOT NULL, reward INTEGER NOT NULL, labor INTEGER NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
